export async function exportBBNTToDocx(bbntData: BBNTData) {
  const doc = new Document({
    styles: {
      default: {
        document: {
          run: {
            size: 26,
            font: "Times New Roman",
            color: "000000",
          },
        },
      },
    },
    sections: [
      {
        properties: {
          page: {
            margin: { top: 720, right: 720, bottom: 720, left: 720 },
          },
