        children: [
          // Header Table
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            rows: [
              new TableRow({
                height: { value: 1000, rule: HeightRule.ATLEAST },
                children: [
                  new TableCell({
                    width: { size: 25, type: WidthType.PERCENTAGE },
                    verticalAlign: VerticalAlign.CENTER,
                    children: [
                      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "B T I", bold: true, size: 36, color: "2B579A" })] })
                    ]
                  }),
                  new TableCell({
                    width: { size: 55, type: WidthType.PERCENTAGE },
                    verticalAlign: VerticalAlign.CENTER,
                    children: [
                      new Paragraph({
                        alignment: AlignmentType.CENTER,
                        children: [new TextRun({ text: "BIÊN BẢN NGHIỆM THU VÀ BÀN GIAO", bold: true, size: 30 })]
                      })
                    ]
                  }),
                  new TableCell({
                    width: { size: 20, type: WidthType.PERCENTAGE },
                    verticalAlign: VerticalAlign.CENTER,
                    children: [
                      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: bbntData.docNumber || "QTMH-BM03.2", bold: true, size: 20 })] })
                    ]
                  })
                ]
              })
            ]
          }),

          new Paragraph({ spacing: { before: 200 } }),
          new Paragraph({
            alignment: AlignmentType.RIGHT,
            children: [new TextRun({ text: `${bbntData.location}, ${bbntData.date}`, italics: true })]
          }),

          new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "1. ĐỐI TƯỢNG:", bold: true })] }),
          new Paragraph({ children: [new TextRun({ text: `- Công trình: ${bbntData.project}` })] }),
          new Paragraph({ children: [new TextRun({ text: `- Hạng mục: ${bbntData.category}` })] }),
          new Paragraph({ children: [new TextRun({ text: `- Địa điểm: ${bbntData.address}` })] }),

          new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "2. Thành phần tham gia nghiệm thu:", bold: true })] }),

          // Use Table for fixed alignment of "Chức vụ" in section 2
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.NONE },
              left: { style: BorderStyle.NONE },
              right: { style: BorderStyle.NONE },
              insideHorizontal: { style: BorderStyle.NONE },
              insideVertical: { style: BorderStyle.NONE },
            },
            rows: [
              // Bên Giao Header
              new TableRow({
                children: [
                  new TableCell({
                    columnSpan: 2,
                    children: [
                      new Paragraph({
                        children: [
                          new TextRun({ text: "BÊN GIAO: ", bold: true, underline: {} }),
                          new TextRun({ text: bbntData.senderCompany, bold: true })
                        ]
                      })
                    ]
                  })
                ]
              }),
              // Bên Giao Rep
              new TableRow({
                children: [
                  new TableCell({
                    width: { size: 45, type: WidthType.PERCENTAGE },
                    children: [new Paragraph({ children: [new TextRun({ text: `- Ông: ${bbntData.senderRepresentative}` })] })]
                  }),
                  new TableCell({
                    width: { size: 55, type: WidthType.PERCENTAGE },
                    children: [new Paragraph({ children: [new TextRun({ text: `Chức vụ: ${bbntData.senderPosition}` })] })]
                  })
                ]
              }),
              // Spacer row
              new TableRow({ children: [new TableCell({ children: [new Paragraph({ text: "" })] }), new TableCell({ children: [new Paragraph({ text: "" })] })] }),
              // Bên Nhận Header
              new TableRow({
                children: [
                  new TableCell({
                    columnSpan: 2,
                    children: [
                      new Paragraph({
                        children: [
                          new TextRun({ text: "BÊN NHẬN: ", bold: true, underline: {} }),
                          new TextRun({ text: bbntData.receiverCompany, bold: true })
                        ]
                      })
                    ]
                  })
                ]
              }),
              // Bên Nhận List
              ...bbntData.receiverList.map(r => 
                new TableRow({
                  children: [
                    new TableCell({
                      width: { size: 45, type: WidthType.PERCENTAGE },
                      children: [new Paragraph({ children: [new TextRun({ text: `- ${r.salutation}: ${r.name}` })] })]
