          new Paragraph({ children: [new TextRun({ text: bbntData.locationDetail, italics: true })] }),

          new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "4. Tài liệu làm căn cứ:", bold: true })] }),
          ...bbntData.grounds.map(g => new Paragraph({ children: [new TextRun({ text: `- ${g}` })] })),

          new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "5. Khối lượng công việc:", bold: true })] }),
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            rows: [
              new TableRow({
                children: ["Stt", "Diễn giải", "ĐVT", "SL yêu cầu", "SL nghiệm thu", "Ghi chú"].map(h => 
                  new TableCell({ children: [new Paragraph({ text: h, bold: true, alignment: AlignmentType.CENTER })] })
                )
              }),
              ...bbntData.items.map(it => new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ text: it.stt.toString(), alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: it.description })] }),
                  new TableCell({ children: [new Paragraph({ text: it.unit, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: it.requestedQty.toLocaleString('vi-VN'), alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: it.acceptedQty.toLocaleString('vi-VN'), alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: "" })] }),
                ]
              }))
            ]
          }),

          // Sửa đổi phần Đánh giá để xuống dòng
          new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "6. ĐÁNH GIÁ:", bold: true })] }),
          new Paragraph({ indent: { left: 425 }, children: [new TextRun({ text: "- Về yêu cầu chất lượng dịch vụ: đạt yêu cầu." })] }),
          new Paragraph({ indent: { left: 425 }, children: [new TextRun({ text: "- Về ý kiến khác (nếu có): không có." })] }),

          // Sửa đổi phần Kết luận để xuống dòng
          new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "7. KẾT LUẬN:", bold: true })] }),
          new Paragraph({ indent: { left: 425 }, children: [new TextRun({ text: "- Đồng ý nghiệm thu theo khối lượng như trên." })] }),

          new Paragraph({ spacing: { before: 600 } }),
          new Paragraph({ children: [new TextRun({ text: "CHỮ KÝ CÁC BÊN", bold: true, underline: {} })], alignment: AlignmentType.CENTER }),
          new Paragraph({ spacing: { before: 200 } }),

          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.NONE },
              left: { style: BorderStyle.NONE },
              right: { style: BorderStyle.NONE },
              insideHorizontal: { style: BorderStyle.NONE },
              insideVertical: { style: BorderStyle.NONE },
            },
            rows: [
              new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: bbntData.senderCompany, bold: true })], alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: bbntData.receiverCompany, bold: true })], alignment: AlignmentType.CENTER })] }),
                ]
              }),
              new TableRow({ height: { value: 1500, rule: HeightRule.ATLEAST }, children: [new TableCell({ children: [] }), new TableCell({ children: [] })] }),
              new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: bbntData.senderRepresentative, bold: true })], alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Vũ Phi Hùng", bold: true })], alignment: AlignmentType.CENTER })] }),
                ]
              })
