function calculateNextDay(dateStr: string): string {
  try {
    // Regex bắt chuỗi định dạng: ngày dd tháng mm năm yyyy
    const match = dateStr.match(/ngày\s+(\d{1,2})\s+tháng\s+(\d{1,2})\s+năm\s+(\d{4})/i);
    if (match) {
      const day = parseInt(match[1], 10);
      const month = parseInt(match[2], 10) - 1; // Tháng trong JS bắt đầu từ 0
      const year = parseInt(match[3], 10);

      const date = new Date(year, month, day);
      // Cộng thêm 1 ngày
      date.setDate(date.getDate() + 1);

      const newDay = date.getDate().toString().padStart(2, '0');
      const newMonth = (date.getMonth() + 1).toString().padStart(2, '0');
      const newYear = date.getFullYear();

      return `ngày ${newDay} tháng ${newMonth} năm ${newYear}`;
    }
  } catch (e) {
    console.warn("Không thể tính toán ngày tiếp theo từ:", dateStr);
  }
  // Trả về chuỗi gốc nếu không parse được
  return dateStr;
}

export async function extractDataFromFile(fileBase64: string, mimeType: string): Promise<ExtractionResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Bạn là một chuyên gia trích xuất dữ liệu hành chính từ tài liệu xây dựng Việt Nam.
  Hãy phân tích kỹ tệp tin đính kèm và thực hiện trích xuất dữ liệu cho HAI biểu mẫu:

  1. BIỂU MẪU BM02 (TỜ TRÌNH PHÊ DUYỆT KINH PHÍ):
     - Title: Trích xuất ĐẦY ĐỦ, CHI TIẾT và CHÍNH XÁC nội dung công việc (hạng mục, vị trí, tên dự án). 
       QUAN TRỌNG: Chỉ trả về phần nội dung chi tiết công việc. KHÔNG bao gồm các cụm từ hành chính như "V/v", "Phê duyệt", "Tờ trình" ở đầu câu.
       Ví dụ mong muốn: "Đổ bê tông lót đà kiềng căn 58A Lô N7 – N8 thuộc dự án Khu nhà ở độc lập biệt thự Sunflower".
       Giữ nguyên các thông tin cụ thể về số căn (58A, 58B...), số lô (Lô N7-N8).
     - ProposingCompany: Trích xuất tên công ty gửi đề nghị (Ví dụ: TIẾN ĐOÀN).
     - Date: Trả về định dạng "ngày [dd] tháng [mm] năm [yyyy]".
     - Location: "Tp. Hồ Chí Minh".
     - Grounds:
        1. "Căn cứ Phiếu đề nghị về việc cung cấp vật tư của Công ty [Tên Công ty]"
        2. "Căn cứ Báo giá của Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước"
     - Items: Danh sách vật tư (Tên, Đvt, SL, Đơn giá).

  2. BIỂU MẪU BM03.2 (BIÊN BẢN NGHIỆM THU VÀ BÀN GIAO):
     - Date: Trích xuất ngày văn bản nếu có.
     - Location: "Tp. Hồ Chí Minh".
     - Bên Giao: Mặc định là "Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước". 
     - Người đại diện Bên Giao: Nếu không thấy trong tài liệu, hãy để là "Trần Thành Tài", chức vụ "Giám đốc chi nhánh".
     - Bên Nhận: "Công ty TNHH MTV Thương Mại Becamex".
     - Thành phần Bên Nhận: Cố định danh sách gồm: Nguyễn Xuân Nam (Phó Giám đốc), Lương Thị Ngọc Trinh (Kế toán trưởng), Đỗ Thế Viễn (Phó phòng KT), Lê Minh Chánh (NV), Trần Nam Anh (NV).
     - Thời gian (Mặc định): Bắt đầu lúc: 15h. Kết thúc lúc: 16h.
     - Tài liệu làm căn cứ (Mặc định nếu không tìm thấy số cụ thể): 
        1. "Hợp đồng nguyên tắc số 04/HĐNT2025 ký ngày 03/02/2025;"
        2. "Tờ trình phê duyệt dự trù kinh phí mua vật tư BTI-QTMH-BM02-25090014;"
        3. "Biên bản giao nhận hàng;"
     - Items: Bảng khối lượng (Diễn giải, ĐVT, SL yêu cầu, SL nghiệm thu).

  Yêu cầu định dạng ngày tháng: Nếu thấy 26/11/2025, phải chuyển thành "ngày 26 tháng 11 năm 2025".
  Trả về JSON theo cấu trúc quy định.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: fileBase64,
            },
          },
          { text: prompt },
        ],
      },
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          bm02: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              proposingCompany: { type: Type.STRING },
              date: { type: Type.STRING },
              location: { type: Type.STRING },
              grounds: { type: Type.ARRAY, items: { type: Type.STRING } },
              items: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    unit: { type: Type.STRING },
                    quantity: { type: Type.NUMBER },
                    unitPrice: { type: Type.NUMBER }
                  }
                }
              }
            }
          },
          bbnt: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              date: { type: Type.STRING },
              project: { type: Type.STRING },
              category: { type: Type.STRING },
              address: { type: Type.STRING },
              senderCompany: { type: Type.STRING },
              senderRepresentative: { type: Type.STRING },
              senderPosition: { type: Type.STRING },
              startTime: { type: Type.STRING },
              startDate: { type: Type.STRING },
              endTime: { type: Type.STRING },
              endDate: { type: Type.STRING },
              grounds: { type: Type.ARRAY, items: { type: Type.STRING } },
              items: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    description: { type: Type.STRING },
                    unit: { type: Type.STRING },
                    requestedQty: { type: Type.NUMBER },
                    acceptedQty: { type: Type.NUMBER }
                  }
                }
              }
            }
          }
        }
      },
    },
  });

  const rawData = JSON.parse(response.text);
  const proposingCo = rawData.bm02?.proposingCompany || '...';
  const defaultConcreteCompany = "Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước";

  // Xử lý logic ngày tháng: BBNT = BM02 + 1 ngày
  const bm02Date = rawData.bm02?.date || 'ngày ... tháng ... năm 2025';
  const bbntDate = calculateNextDay(bm02Date);

  // Xử lý tiêu đề BM02
  let extractedContent = rawData.bm02?.title || '';
  // Làm sạch chuỗi nếu AI lỡ đưa cả tiền tố vào (phòng hờ)
  extractedContent = extractedContent.replace(/^(V\/v|Phê duyệt|Tờ trình).*?[:]\s*/i, "").trim();
  // Xóa dấu chấm cuối câu nếu có
  extractedContent = extractedContent.replace(/\.+$/, "");

  // Ghép với tiền tố cố định
  const finalTitle = extractedContent 
    ? `Phê duyệt dự trù kinh phí mua vật tư bê tông: ${extractedContent}`
    : 'Phê duyệt dự trù kinh phí mua vật tư bê tông...';

  const bm02: FormData = {
    docNumber: 'QTMH-BM02',
    title: finalTitle,
    date: bm02Date,
    location: rawData.bm02?.location || 'Tp. Hồ Chí Minh',
    recipients: ['Hội Đồng Thành Viên', 'BGĐ Công ty TNHH MTV Thương Mại Becamex'],
    grounds: rawData.bm02?.grounds && rawData.bm02.grounds.length > 0 ? rawData.bm02.grounds : [
      `Căn cứ Phiếu đề nghị về việc cung cấp vật tư của Công ty ${proposingCo}`,
      `Căn cứ Báo giá của ${defaultConcreteCompany}`
    ],
    items: (rawData.bm02?.items || []).map((it: any, idx: number) => ({
      id: Math.random().toString(36).substr(2, 9),
      stt: idx + 1,
      name: it.name,
      unit: it.unit || 'm3',
      quantity: it.quantity || 0,
      unitPrice: it.unitPrice || 0,
      total: (it.quantity || 0) * (it.unitPrice || 0),
      note: ''
    })),
    totalAmount: (rawData.bm02?.items || []).reduce((s: number, it: any) => s + (it.quantity * it.unitPrice || 0), 0),
    proposingCompany: proposingCo
  };

  const bbnt: BBNTData = {
    docNumber: 'QTMH-BM03.2',
    location: rawData.bbnt?.location || 'Tp. Hồ Chí Minh',
    date: bbntDate,
    project: rawData.bbnt?.project || '',
    category: rawData.bbnt?.category || '',
    address: rawData.bbnt?.address || '',
    senderCompany: rawData.bbnt?.senderCompany || defaultConcreteCompany,
    senderRepresentative: rawData.bbnt?.senderRepresentative || 'Trần Thành Tài',
    senderPosition: rawData.bbnt?.senderPosition || 'Giám đốc chi nhánh',
    receiverCompany: 'Công ty TNHH MTV Thương Mại Becamex',
    receiverList: [
      { name: 'Nguyễn Xuân Nam', position: 'Phó Giám đốc', salutation: 'Ông' },
      { name: 'Lương Thị Ngọc Trinh', position: 'Kế toán trưởng', salutation: 'Bà' },
      { name: 'Đỗ Thế Viễn', position: 'Phó phòng KT', salutation: 'Ông' },
      { name: 'Lê Minh Chánh', position: 'NV', salutation: 'Ông' },
      { name: 'Trần Nam Anh', position: 'NV', salutation: 'Ông' }
    ],
    startTime: rawData.bbnt?.startTime || '15h',
    startDate: bbntDate, // Ngày bắt đầu nghiệm thu theo ngày văn bản BBNT
    endTime: rawData.bbnt?.endTime || '16h',
    endDate: bbntDate,   // Ngày kết thúc nghiệm thu theo ngày văn bản BBNT
    locationDetail: 'Tại: Công trình',
    grounds: rawData.bbnt?.grounds && rawData.bbnt.grounds.length > 0 ? rawData.bbnt.grounds : [
      "Hợp đồng nguyên tắc số 04/HĐNT2025 ký ngày 03/02/2025;",
      "Tờ trình phê duyệt dự trù kinh phí mua vật tư BTI-QTMH-BM02-25090014;",
      "Biên bản giao nhận hàng;"
    ],
    items: (rawData.bbnt?.items || []).map((it: any, idx: number) => ({
      id: Math.random().toString(36).substr(2, 9),
      stt: idx + 1,
      description: it.description || '',
      unit: it.unit || '',
      requestedQty: it.requestedQty || 0,
      acceptedQty: it.acceptedQty || 0,
      note: ''
    }))
  };

  return { bm02, bbnt };
}
